# ---- Terraform guide ----
TF=[('1. Installation','Install Terraform and the Azure CLI, then verify.',[('Shell','# Windows\nwinget install Hashicorp.Terraform\n# macOS\nbrew tap hashicorp/tap && brew install hashicorp/tap/terraform\n# Verify\nterraform -version\naz --version')],'Terraform is distributed by HashiCorp; the Azure CLI is optional but simplest for local sign-in.'),
('2. Azure authentication','Local use signs in with the Azure CLI. Automation uses a service principal or OIDC.',[('Shell','az login\naz account set --subscription "<subscription-id>"'),('Shell','# Service principal for automation\nexport ARM_CLIENT_ID="<app-id>"\nexport ARM_TENANT_ID="<tenant-id>"\nexport ARM_SUBSCRIPTION_ID="<subscription-id>"\nexport ARM_CLIENT_SECRET="<secret>"   # or use OIDC: export ARM_USE_OIDC=true')],'Portal side: create the identity with the App registration and RBAC assignment SOPs.'),
('3. Provider','Declare the AzureRM provider and pin its version.',[('Terraform','terraform {\n  required_version = ">= 1.5"\n  required_providers {\n    azurerm = {\n      source  = "hashicorp/azurerm"\n      version = "~> 4.0"\n    }\n  }\n}\n\nprovider "azurerm" {\n  features {}\n  subscription_id = var.subscription_id\n}')],'AzureRM 4.x requires the subscription ID to be set.'),
('4. Resource creation','Create a resource group, VNet and subnet, then run the standard workflow.',[('Terraform','resource "azurerm_resource_group" "rg" {\n  name     = "rg-app-dev-001"\n  location = "centralindia"\n}\n\nresource "azurerm_virtual_network" "vnet" {\n  name                = "vnet-app-dev"\n  location            = azurerm_resource_group.rg.location\n  resource_group_name = azurerm_resource_group.rg.name\n  address_space       = ["10.10.0.0/16"]\n}\n\nresource "azurerm_subnet" "app" {\n  name                 = "snet-app"\n  resource_group_name  = azurerm_resource_group.rg.name\n  virtual_network_name = azurerm_virtual_network.vnet.name\n  address_prefixes     = ["10.10.1.0/24"]\n}'),('Shell','terraform init\nterraform fmt\nterraform validate\nterraform plan -out tfplan\nterraform apply tfplan\nterraform destroy')],'plan shows changes without making them; apply performs them.'),
('5. Variables','Parameterize configuration with typed variables and validation.',[('Terraform','variable "location" {\n  type        = string\n  description = "Azure region"\n  default     = "centralindia"\n}\n\nvariable "environment" {\n  type = string\n  validation {\n    condition     = contains(["dev", "test", "prod"], var.environment)\n    error_message = "Use dev, test or prod."\n  }\n}'),('Shell','terraform apply -var="environment=dev"\n# or terraform.tfvars, *.auto.tfvars, TF_VAR_environment')],'Precedence: environment variables, terraform.tfvars, auto.tfvars, then -var and -var-file.'),
('6. Outputs and data sources','Expose values and read existing objects.',[('Terraform','output "resource_group_id" {\n  value = azurerm_resource_group.rg.id\n}\n\noutput "connection_string" {\n  value     = "<example>"\n  sensitive = true\n}\n\ndata "azurerm_client_config" "current" {}\n\ndata "azurerm_resource_group" "existing" {\n  name = "rg-shared"\n}')],'Sensitive outputs are hidden in the CLI but still stored in state.'),
('7. State','State maps your configuration to real resources.',[('Shell','terraform state list\nterraform state show azurerm_resource_group.rg\nterraform state mv azurerm_resource_group.rg azurerm_resource_group.main\nterraform state rm azurerm_resource_group.rg')],'State can contain secrets. Never commit terraform.tfstate to source control.'),
('8. Backend and state locking','Store state in Azure Storage; the blob lease locks it during changes.',[('Terraform','terraform {\n  backend "azurerm" {\n    resource_group_name  = "rg-tfstate"\n    storage_account_name = "sttfstate001"\n    container_name       = "tfstate"\n    key                  = "prod.terraform.tfstate"\n    use_azuread_auth     = true\n  }\n}')],'Portal side: create the storage account and container with the Storage SOP, enable versioning and soft delete, and grant Storage Blob Data Contributor.'),
('9. Modules','Reuse tested building blocks.',[('Terraform','module "network" {\n  source        = "./modules/network"\n  location      = var.location\n  address_space = ["10.10.0.0/16"]\n}\n\noutput "vnet_id" {\n  value = module.network.vnet_id\n}')],'A module is a folder with main.tf, variables.tf and outputs.tf.'),
('10. Import','Bring existing portal-created resources under Terraform.',[('Shell','terraform import azurerm_resource_group.rg /subscriptions/<sub-id>/resourceGroups/rg-app-dev-001'),('Terraform','import {\n  to = azurerm_resource_group.rg\n  id = "/subscriptions/<sub-id>/resourceGroups/rg-app-dev-001"\n}')],'Write the matching resource block first; run plan to confirm no unexpected changes.'),
('11. Workspaces','Maintain multiple states from one configuration.',[('Shell','terraform workspace new dev\nterraform workspace select dev\nterraform workspace list')],'Workspaces share a backend. For strong separation between environments prefer separate state files or directories.'),
('12. Lifecycle and depends_on','Control replacement and ordering.',[('Terraform','resource "azurerm_storage_account" "sa" {\n  # ...\n  lifecycle {\n    prevent_destroy = true\n    ignore_changes  = [tags]\n  }\n}\n\nresource "azurerm_role_assignment" "ra" {\n  # ...\n  depends_on = [azurerm_storage_account.sa]\n}')],'Terraform infers most dependencies from references; use depends_on only when a dependency is hidden.'),
('13. CI/CD','Plan on pull request, apply after approval, authenticate with OIDC.',[('YAML','name: terraform\non: pull_request\npermissions:\n  id-token: write\n  contents: read\njobs:\n  plan:\n    runs-on: ubuntu-latest\n    env:\n      ARM_USE_OIDC: "true"\n      ARM_CLIENT_ID: ${{ secrets.AZURE_CLIENT_ID }}\n      ARM_TENANT_ID: ${{ secrets.AZURE_TENANT_ID }}\n      ARM_SUBSCRIPTION_ID: ${{ secrets.AZURE_SUBSCRIPTION_ID }}\n    steps:\n      - uses: actions/checkout@v4\n      - uses: hashicorp/setup-terraform@v3\n      - run: terraform init\n      - run: terraform plan -out tfplan')],'Portal side: add a federated credential to the app registration instead of storing a secret.'),
('14. Enterprise architecture','Structure for teams and environments.',[('Text','infra/\n  modules/            # reusable modules (network, storage, aks)\n  live/\n    platform/         # hub network, policy, monitoring\n    landing-zones/\n      app1-dev/\n      app1-prod/\n  pipelines/          # plan, approve, apply')],'Principles: remote state per workload and environment, pinned module versions, plan approval gates, policy as code, least-privilege pipeline identities, drift detection.')]
tf='<h1>Terraform Guide</h1>'
for i,(t,p,cs,n) in enumerate(TF):
    tf+=f'<h2 id="tf-{i}">{E(t)}</h2><p>{E(p)}</p>'+''.join(f'<p class="src"><b>{k}</b></p><pre class="cmd">{E(c)}</pre>' for k,c in cs)+f'<div class="co co-note"><b>💡 Note</b> {E(n)}</div>'
tf+='<h2>Documentation</h2><p><a href="https://learn.microsoft.com/en-us/azure/developer/terraform/overview" target="_blank" rel="noopener">Microsoft Learn: Terraform on Azure</a> · <a href="https://learn.microsoft.com/en-us/azure/developer/terraform/authenticate-to-azure" target="_blank" rel="noopener">Authenticate to Azure</a> · <a href="https://learn.microsoft.com/en-us/azure/developer/terraform/store-state-in-azure-storage" target="_blank" rel="noopener">Store state in Azure Storage</a> · <a href="https://registry.terraform.io/providers/hashicorp/azurerm/latest/docs" target="_blank" rel="noopener">AzureRM provider reference (HashiCorp)</a></p>'
